USE travel_agent;
CREATE TABLE IF NOT EXISTS auth_account (id BIGINT NOT NULL AUTO_INCREMENT, user_id VARCHAR(64) NOT NULL, username VARCHAR(64) NOT NULL, password_hash VARCHAR(100) NOT NULL, email VARCHAR(255) NULL, email_verified TINYINT NOT NULL DEFAULT 0, status VARCHAR(16) NOT NULL DEFAULT 'active', failed_attempts INT NOT NULL DEFAULT 0, locked_until DATETIME NULL, last_login_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uk_auth_username(username), UNIQUE KEY uk_auth_email(email), UNIQUE KEY uk_auth_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS auth_session (id BIGINT NOT NULL AUTO_INCREMENT, token_hash CHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, expires_at DATETIME NOT NULL, revoked_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uk_auth_token(token_hash), KEY idx_auth_session_user(user_id,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
